function snapshotCharacterHits(labelRows, rayRows, clientX, clientY) {
  // Rows are projections of actual label containment / actual ray intersections.
  // This function never grows a new screen-radius hit area.
  var rows = labelRows.length ? labelRows : rayRows;
  var out = [], seenNodes = [], ids = Object.create(null);
  rows.forEach(function(r, index) {
    var n=r.node, d=n && n.data, p=r.screen;
    if(!n || n.kind!=='char' || n.render===false || !n.g || !n.g.visible || (!labelRows.length && !(n.alpha>0.3))) return;
    if(!p || !isFinite(p.x) || !isFinite(p.y) || !isFinite(p.z) || p.z < -1 || p.z > 1) return;
    if(seenNodes.indexOf(n)>=0) return;
    seenNodes.push(n);
    var id=d && d.id!=null ? String(d.id) : d && d.entityId!=null ? String(d.entityId) : null;
    var name=d && typeof d.name==='string' ? d.name : n.label || '';
    var coherent=!!id && !(d.id!=null && d.entityId!=null && String(d.id)!==String(d.entityId));
    var dx=p.x-clientX,dy=p.y-clientY;
    var item={node:n,key:n.key,id:id,name:name,x:p.x,y:p.y,z:p.z,distance2:dx*dx+dy*dy,
      source:labelRows.length?'label':'sprite',identityStatus:d && d.identityStatus || null,
      selectable:coherent,reason:coherent?'':'缺失或冲突的稳定身份',_ordinal:index};
    out.push(item); if(id) (ids[id] || (ids[id]=[])).push(item);
  });
  Object.keys(ids).forEach(function(id) { if(ids[id].length>1) ids[id].forEach(function(r){r.selectable=false;r.reason='同一ID指向多个渲染节点';}); });
  out.sort(function(a,b){return a.distance2-b.distance2 || a._ordinal-b._ordinal;});
  out.forEach(function(r){delete r._ordinal;});
  return {source:labelRows.length?'label':'sprite',x:clientX,y:clientY,candidates:out,
    ambiguous:out.length>1,selectedId:null};
}
